const body = $json.body || $json;
const candidate = body.candidate || {};
const job = body.job || {};
const questions = body.questions || {};
const cvFile = body.cvFile || null;
const instructions = body.processingInstructions || {};
const clean = (v) => String(v || '').trim();
const safeName = clean(candidate.name || 'Unknown Candidate').replace(/[\\/:*?"<>|]/g, '-').slice(0, 90);
const safePhone = clean(candidate.phone).replace(/[^0-9+]/g, '').slice(-12);
const folderName = `${safeName}${safePhone ? ' - ' + safePhone : ''}`;
const fileExt = cvFile && cvFile.name && cvFile.name.includes('.') ? cvFile.name.split('.').pop().toLowerCase() : '';
const fileType = clean(cvFile && (cvFile.type || fileExt));
const acceptsParsing = Boolean(cvFile && cvFile.base64 && ['pdf','doc','docx'].some(x => fileType.toLowerCase().includes(x) || fileExt === x));
const text = [candidate.name, candidate.field, candidate.experience, candidate.city, candidate.country, candidate.currentLocation, candidate.nationality, candidate.residenceStatus, candidate.workMode, candidate.availability, job.title, questions.interest, questions.strengths, questions.notice, questions.workAuthorization, cvFile && cvFile.name].filter(Boolean).join(' | ');
const lower = text.toLowerCase();
const requiredSignals = ['qiwa','gosi','mudad','muqeem','hr','recruit','saudi','government','payroll','onboarding','candidate','interview'];
const matchedSignals = requiredSignals.filter(s => lower.includes(s));
const saudizationSignals = ['saudi','سعودي','سعودية','gosi','qiwa','قوى','توطين','saudization'].filter(s => lower.includes(s.toLowerCase()));
const score = Math.min(100, 35 + matchedSignals.length * 8 + (acceptsParsing ? 10 : 0) + (candidate.email ? 5 : 0) + (candidate.residenceStatus ? 5 : 0));
const stage = score >= 75 ? 'shortlist' : score >= 55 ? 'review' : 'new';
return { json: { source: body.source || 'website-careers', receivedAt: body.receivedAt || new Date().toISOString(), candidate, job, questions, cvFile: cvFile ? { name: cvFile.name, type: cvFile.type, size: cvFile.size, extension: fileExt, hasBase64: Boolean(cvFile.base64), base64: cvFile.base64 || '', parseable: acceptsParsing } : null, drivePlan: { enabled: Boolean(instructions.createCandidateDriveFolder), parentFolder: 'BP Candidates', candidateFolderName: folderName, originalCvFileName: cvFile && cvFile.name ? `01-original-${cvFile.name}` : '', atsCvDocName: `02-Business-Partner-CV-${safeName}`, employerProfileName: `03-employer-profile-${safeName}`, notionFieldsToUpdate: ['Original CV Drive URL','ATS CV Drive URL','Employer Profile URL','Parsed CV Text','Screening Summary'] }, processingInstructions: { parseCvText: true, saveOriginalCv: true, generateAtsFriendlyCv: true, generateEmployerReadableProfile: true, matchOccupationAgainstSaudizationRules: true, updateNotionWithDriveLinks: true, createApplicationRecordPerJob: true, hidePrivateContactUntilEmployerUnlocked: true }, screening: { score, matchedSignals, saudizationSignals, occupationMatchStatus: saudizationSignals.length ? 'needs-saudization-check' : 'general-check', stage }, notionDatabaseId: body.ats && body.ats.notionDatabaseId, sourcePage: body.ats && body.ats.sourcePage, internalSummary: `${candidate.name || 'Candidate'} applied for ${job.title || 'Candidate Pool'} — score ${score}/100 — ${candidate.country || ''} ${candidate.city || ''}` } };

const norm = $('Normalize ATS Payload').item.json;
const cv = $json;
return { json: Object.assign({}, norm, { cvText: cv.cvText || '', cvTextStatus: cv.cvTextStatus || 'skipped' }) };

const folder = $('Create Candidate Drive Folder').item.json;
let bin = {};
try { bin = $('Convert CV Base64 To Binary').item.binary || {}; } catch (e) {}
if (!bin.data) { try { bin = $('Convert DOCX Base64 To Binary').item.binary || {}; } catch (e) {} }
return { json: { folderId: folder.id, folderLink: folder.webViewLink }, binary: bin.data ? { data: bin.data } : {} };

const norm = $('Normalize ATS Payload').item.json;
const ai = ($('AI Screening Summary').item.json.output) || {};
let drive = { candidateFolderUrl: '', originalCvUrl: '', atsCvDocUrl: '' };
try {
  const folder = $('Create Candidate Drive Folder').item.json;
  const upload = $('Upload Original CV').item.json;
  const atsDoc = $('Create ATS CV Doc').item.json;
  drive = {
    candidateFolderUrl: folder.webViewLink || '',
    originalCvUrl: upload.webViewLink || '',
    atsCvDocUrl: atsDoc.id ? ('https://docs.google.com/document/d/' + atsDoc.id + '/edit') : '',
  };
} catch (e) {}
const stageMap = { shortlist: 'قائمة مختصرة', review: 'فرز', new: 'جديد' };
const stage = (norm.screening && norm.screening.stage) || 'new';
return { json: {
  candidate: norm.candidate || {},
  job: norm.job || {},
  questions: norm.questions || {},
  screening: Object.assign({}, norm.screening, { pipelineStage: stageMap[stage] || 'جديد' }),
  ai,
  drive,
  cvTextStatus: (($('Build Screening Input').item.json || {}).cvTextStatus) || 'skipped',
} };
